# Terraform Module: S3 + RDS + IAM

A complete, production-ready Terraform module implementing the canonical scenario specification.

## Project Structure

```
terraform-module-infra/
├── modules/
│   └── infra/
│       ├── main.tf
│       ├── variables.tf
│       ├── outputs.tf
│       ├── s3.tf
│       ├── rds.tf
│       └── iam.tf
├── environments/
│   ├── dev.tfvars
│   └── prod.tfvars
├── main.tf
├── variables.tf
├── outputs.tf
├── versions.tf
└── README.md
```

---

## Root Module

### `versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }

  # Backend configuration provided at init time:
  # terraform init -backend-config="bucket=tfstate" -backend-config="key=infra" -backend-config="region=us-east-1"
  backend "s3" {}
}
```

### `main.tf` (Root)

```hcl
provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

# Replica provider for prod cross-region replication
provider "aws" {
  alias  = "replica"
  region = var.replica_region

  default_tags {
    tags = {
      Project     = var.project_name
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  }
}

module "infra" {
  source = "./modules/infra"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  project_name   = var.project_name
  environment    = var.environment
  aws_region     = var.aws_region
  replica_region = var.replica_region

  # S3
  enable_replication = var.enable_replication

  # RDS
  db_instance_class    = var.db_instance_class
  db_multi_az          = var.db_multi_az
  db_allocated_storage = var.db_allocated_storage
  db_name              = var.db_name
  db_username          = var.db_username

  # IAM
  oidc_provider_arn = var.oidc_provider_arn
  oidc_subject      = var.oidc_subject
}
```

### `variables.tf` (Root)

```hcl
variable "project_name" {
  description = "Project name used for resource naming"
  type        = string
  default     = "webapp"
}

variable "environment" {
  description = "Deployment environment (dev or prod)"
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "Environment must be dev or prod."
  }
}

variable "aws_region" {
  description = "Primary AWS region"
  type        = string
  default     = "us-east-1"
}

variable "replica_region" {
  description = "Cross-region replica region (prod only)"
  type        = string
  default     = "us-west-2"
}

# --- S3 ---
variable "enable_replication" {
  description = "Enable cross-region S3 replication (prod)"
  type        = bool
  default     = false
}

# --- RDS ---
variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "db_multi_az" {
  description = "Enable Multi-AZ for RDS"
  type        = bool
  default     = false
}

variable "db_allocated_storage" {
  description = "RDS allocated storage in GB"
  type        = number
  default     = 20
}

variable "db_name" {
  description = "Database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Database master username"
  type        = string
  default     = "dbadmin"
  sensitive   = true
}

# --- IAM ---
variable "oidc_provider_arn" {
  description = "EKS OIDC provider ARN for IRSA (prod)"
  type        = string
  default     = ""
}

variable "oidc_subject" {
  description = "OIDC subject for service account (e.g., system:serviceaccount:default:webapp)"
  type        = string
  default     = ""
}
```

### `outputs.tf` (Root)

```hcl
output "bucket_name" {
  description = "S3 bucket name"
  value       = module.infra.bucket_name
}

output "bucket_arn" {
  description = "S3 bucket ARN"
  value       = module.infra.bucket_arn
}

output "db_endpoint" {
  description = "RDS endpoint"
  value       = module.infra.db_endpoint
}

output "db_connection_secret_arn" {
  description = "Secrets Manager ARN for DB connection string"
  value       = module.infra.db_connection_secret_arn
}

output "service_account_role_arn" {
  description = "IAM role ARN for service account"
  value       = module.infra.service_account_role_arn
}
```

