## Infra Module

### `modules/infra/variables.tf`

```hcl
variable "project_name" {
  type = string
}

variable "environment" {
  type = string
}

variable "aws_region" {
  type = string
}

variable "replica_region" {
  type = string
}

variable "enable_replication" {
  type = bool
}

variable "db_instance_class" {
  type = string
}

variable "db_multi_az" {
  type = bool
}

variable "db_allocated_storage" {
  type = number
}

variable "db_name" {
  type = string
}

variable "db_username" {
  type      = string
  sensitive = true
}

variable "oidc_provider_arn" {
  type = string
}

variable "oidc_subject" {
  type = string
}
```

### `modules/infra/main.tf`

```hcl
terraform {
  required_providers {
    aws = {
      source                = "hashicorp/aws"
      configuration_aliases = [aws, aws.replica]
    }
  }
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"
  is_prod     = var.environment == "prod"

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
  }
}
```

### `modules/infra/s3.tf`

```hcl
# ---------------------------------------------------------------------------
# KMS key for S3 encryption (prod uses KMS; dev uses AES-256 for cost)
# ---------------------------------------------------------------------------
resource "aws_kms_key" "s3" {
  count = local.is_prod ? 1 : 0

  description             = "${local.name_prefix} S3 encryption key"
  deletion_window_in_days = 14
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "s3" {
  count = local.is_prod ? 1 : 0

  name          = "alias/${local.name_prefix}-s3"
  target_key_id = aws_kms_key.s3[0].key_id
}

# ---------------------------------------------------------------------------
# Primary bucket
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "assets" {
  bucket = "${local.name_prefix}-assets-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-assets"
  })
}

data "aws_caller_identity" "current" {}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.is_prod ? "aws:kms" : "AES256"
      kms_master_key_id = local.is_prod ? aws_kms_key.s3[0].arn : null
    }
    bucket_key_enabled = local.is_prod
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# Cross-region replication (prod only)
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = "${local.name_prefix}-assets-replica-${data.aws_caller_identity.current.account_id}"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-assets-replica"
  })
}

resource "aws_s3_bucket_versioning" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  count    = var.enable_replication ? 1 : 0
  provider = aws.replica

  bucket = aws_s3_bucket.replica[0].id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Replication IAM role
resource "aws_iam_role" "replication" {
  count = var.enable_replication ? 1 : 0

  name = "${local.name_prefix}-s3-replication"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        Service = "s3.amazonaws.com"
      }
    }]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "replication" {
  count = var.enable_replication ? 1 : 0

  name = "${local.name_prefix}-s3-replication"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = aws_s3_bucket.assets.arn
      },
      {
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.assets.arn}/*"
      },
      {
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.replica[0].arn}/*"
      }
    ]
  })
}

resource "aws_s3_bucket_replication_configuration" "assets" {
  count = var.enable_replication ? 1 : 0

  depends_on = [aws_s3_bucket_versioning.assets]

  bucket = aws_s3_bucket.assets.id
  role   = aws_iam_role.replication[0].arn

  rule {
    id     = "replicate-all"
    status = "Enabled"

    destination {
      bucket        = aws_s3_bucket.replica[0].arn
      storage_class = "STANDARD"
    }
  }
}
```

### `modules/infra/rds.tf`

```hcl
# ---------------------------------------------------------------------------
# Random password — never stored in Git; stored in Secrets Manager
# ---------------------------------------------------------------------------
resource "random_password" "db" {
  length           = 32
  special          = true
  override_special = "!#$%&*()-_=+[]{}<>:?"
}

# ---------------------------------------------------------------------------
# KMS key for RDS encryption
# ---------------------------------------------------------------------------
resource "aws_kms_key" "rds" {
  description             = "${local.name_prefix} RDS encryption key"
  deletion_window_in_days = 14
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "rds" {
  name          = "alias/${local.name_prefix}-rds"
  target_key_id = aws_kms_key.rds.key_id
}

# ---------------------------------------------------------------------------
# Subnet group
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "${local.name_prefix}-db"
  subnet_ids = data.aws_subnets.default.ids

  tags = local.common_tags
}

data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "default" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

# ---------------------------------------------------------------------------
# Security group — no public access
# ---------------------------------------------------------------------------
resource "aws_security_group" "rds" {
  name        = "${local.name_prefix}-rds"
  description = "RDS PostgreSQL access"
  vpc_id      = data.aws_vpc.default.id

  ingress {
    description = "PostgreSQL from VPC"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.default.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# RDS PostgreSQL instance
# ---------------------------------------------------------------------------
resource "aws_db_instance" "main" {
  identifier = "${local.name_prefix}-postgres"

  # Engine
  engine               = "postgres"
  engine_version       = "16.3"
  instance_class       = var.db_instance_class
  allocated_storage    = var.db_allocated_storage
  max_allocated_storage = var.db_allocated_storage * 2
  storage_type         = "gp3"
  storage_encrypted    = true
  kms_key_id           = aws_kms_key.rds.arn

  # Database
  db_name  = var.db_name
  username = var.db_username
  password = random_password.db.result

  # Networking
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  publicly_accessible    = false
  multi_az               = var.db_multi_az

  # Backup & maintenance
  backup_retention_period   = local.is_prod ? 14 : 7
  backup_window             = "03:00-04:00"
  maintenance_window        = "sun:04:30-sun:05:30"
  copy_tags_to_snapshot     = true
  delete_automated_backups  = !local.is_prod

  # Protection
  deletion_protection = true
  skip_final_snapshot = !local.is_prod
  final_snapshot_identifier = local.is_prod ? "${local.name_prefix}-final-snapshot" : null

  # Monitoring
  performance_insights_enabled          = local.is_prod
  performance_insights_retention_period = local.is_prod ? 7 : null
  enabled_cloudwatch_logs_exports       = ["postgresql", "upgrade"]

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-postgres"
  })
}

# ---------------------------------------------------------------------------
# Store connection string in Secrets Manager (never in Git)
# ---------------------------------------------------------------------------
resource "aws_secretsmanager_secret" "db_connection" {
  name                    = "${local.name_prefix}/db-connection-string"
  description             = "PostgreSQL connection string for ${local.name_prefix}"
  recovery_window_in_days = local.is_prod ? 14 : 0
  kms_key_id              = aws_kms_key.rds.arn

  tags = local.common_tags
}

resource "aws_secretsmanager_secret_version" "db_connection" {
  secret_id = aws_secretsmanager_secret.db_connection.id

  secret_string = jsonencode({
    engine   = "postgresql"
    host     = aws_db_instance.main.address
    port     = aws_db_instance.main.port
    dbname   = var.db_name
    username = var.db_username
    password = random_password.db.result
    url      = "postgresql://${var.db_username}:${random_password.db.result}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${var.db_name}"
  })
}
```

### `modules/infra/iam.tf`

```hcl
# ---------------------------------------------------------------------------
# IAM Role for service account (IRSA or instance profile)
# ---------------------------------------------------------------------------

# Trust policy: OIDC for prod, broad assume-role for dev
locals {
  assume_role_policy = var.oidc_provider_arn != "" ? jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Federated = var.oidc_provider_arn
      }
      Action = "sts:AssumeRoleWithWebIdentity"
      Condition = {
        StringEquals = {
          "${replace(var.oidc_provider_arn, "/^(.*provider\\/)/", "")}:sub" = var.oidc_subject
          "${replace(var.oidc_provider_arn, "/^(.*provider\\/)/", "")}:aud" = "sts.amazonaws.com"
        }
      }
    }]
    }) : jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role" "service_account" {
  name               = "${local.name_prefix}-service-account"
  assume_role_policy = local.assume_role_policy

  tags = local.common_tags
}

# ---------------------------------------------------------------------------
# Least-privilege policy: scoped to specific resources
# ---------------------------------------------------------------------------
resource "aws_iam_role_policy" "service_account" {
  name = "${local.name_prefix}-service-account"
  role = aws_iam_role.service_account.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      # S3 access — scoped to the assets bucket
      [
        {
          Sid    = "S3BucketAccess"
          Effect = "Allow"
          Action = local.is_prod ? [
            "s3:GetObject",
            "s3:PutObject",
            "s3:DeleteObject",
            "s3:ListBucket",
            "s3:GetObjectVersion"
            ] : [
            "s3:GetObject",
            "s3:PutObject",
            "s3:ListBucket"
          ]
          Resource = [
            aws_s3_bucket.assets.arn,
            "${aws_s3_bucket.assets.arn}/*"
          ]
        }
      ],
      # Secrets Manager — read DB connection string only
      [
        {
          Sid    = "SecretsManagerRead"
          Effect = "Allow"
          Action = [
            "secretsmanager:GetSecretValue",
            "secretsmanager:DescribeSecret"
          ]
          Resource = aws_secretsmanager_secret.db_connection.arn
        }
      ],
      # KMS decrypt for encrypted resources
      local.is_prod ? [
        {
          Sid    = "KMSDecrypt"
          Effect = "Allow"
          Action = [
            "kms:Decrypt",
            "kms:DescribeKey",
            "kms:GenerateDataKey"
          ]
          Resource = [
            aws_kms_key.s3[0].arn,
            aws_kms_key.rds.arn
          ]
        }
        ] : [
        {
          Sid    = "KMSDecrypt"
          Effect = "Allow"
          Action = [
            "kms:Decrypt",
            "kms:DescribeKey"
          ]
          Resource = aws_kms_key.rds.arn
        }
      ]
    )
  })
}

# ---------------------------------------------------------------------------
# IAM user for dev programmatic access (prod uses OIDC/IRSA only)
# ---------------------------------------------------------------------------
resource "aws_iam_user" "dev_service" {
  count = local.is_prod ? 0 : 1

  name = "${local.name_prefix}-service"
  tags = local.common_tags
}

resource "aws_iam_user_policy_attachment" "dev_service" {
  count = local.is_prod ? 0 : 1

  user       = aws_iam_user.dev_service[0].name
  policy_arn = aws_iam_policy.dev_service[0].arn
}

resource "aws_iam_policy" "dev_service" {
  count = local.is_prod ? 0 : 1

  name        = "${local.name_prefix}-dev-service"
  description = "Dev service account policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3Access"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.assets.arn,
          "${aws_s3_bucket.assets.arn}/*"
        ]
      },
      {
        Sid    = "SecretsRead"
        Effect = "Allow"
        Action = [
          "secretsmanager:GetSecretValue"
        ]
        Resource = aws_secretsmanager_secret.db_connection.arn
      }
    ]
  })

  tags = local.common_tags
}
```

